// Create a caller-owned backing buffer that must outlive the xbps_data_t lifetime.
// We allocate <= 1536 bytes to limit per-call allocation and return the buffer as an output
// to keep it alive in the fuzzer's object pool.
std::string src = FUZZ_PARAM_STR();
size_t cap = src.size();
if (cap > 1536) cap = 1536; // cap allocation size
size_t length = 0;
if (cap > 0) {
    length = (size_t)(*FUZZ_PARAM(unsigned int) % (cap + 1));
}
