import os
import random
import struct
from typing import List

# This generator targets many stubs that consume arbitrary C-strings and filenames.
# We produce a small corpus element that concatenates multiple NUL-terminated strings
# so the harness can draw FUZZ_PARAM_STR and FUZZ_PARAM_FILENAME from it.
#
# Layout we generate:
#  [count:u8]
#  then count entries of:
#    kind:u8  (0 = generic string, 1 = filename)
#    len:u16  length excluding NUL (<= 512)
#    bytes[len]
#    NUL (0x00)
# The harness typically reads in-order; by mixing kinds we seed both STR and FILENAME.
# Filenames are crafted to be plausible local paths that the harness may create/fill.

SAFE_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-"

PKG_NAMES = [
    "bash", "coreutils", "libc", "openssl", "curl", "python3", "linux", "mesa",
    "xz", "zlib", "binutils", "gcc", "glibc", "dbus", "systemd", "vim", "nano",
]

ARCHES = ["x86_64", "aarch64", "armv7l", "i686", "ppc64le", "riscv64", "noarch"]

EXTS = [".xbps", ".plist", ".sig2", ".tar", ".tar.xz", ".txt", ".conf"]

PAT_OPERATORS = ["=", ">=", "<=", "<", ">"]


def rseed(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    return "".join(r.choice(SAFE_CHARS) for _ in range(n))


def rand_pkgver(r: random.Random) -> str:
    name = r.choice(PKG_NAMES)
    ver = f"{r.randint(0,9)}.{r.randint(0,9)}.{r.randint(0,20)}"
    rev = f"_{r.randint(1,5)}" if r.random() < 0.5 else ""
    return f"{name}-{ver}{rev}"


def rand_pattern(r: random.Random) -> str:
    name = r.choice(PKG_NAMES)
    if r.random() < 0.5:
        # wildcard
        return name + "-*"
    op = r.choice(PAT_OPERATORS)
    ver = f"{r.randint(0,9)}.{r.randint(0,9)}.{r.randint(0,20)}"
    return f"{name}{op}{ver}"


def rand_repo_uri(r: random.Random) -> str:
    # Mostly local paths to avoid network
    if r.random() < 0.7:
        base = "/tmp" if os.name != "nt" else os.getcwd()
        comp = rand_ascii(r, 3, 12)
        return f"file://{base}/{comp}"
    # Occasionally http style
    host = rand_ascii(r, 4, 10).lower()
    path = rand_ascii(r, 3, 8)
    return f"http://{host}.example.com/{path}"


def rand_filename(r: random.Random) -> str:
    # Create plausible existing temp file path under CWD or /tmp
    base_dir = os.getcwd()
    sub = rand_ascii(r, 3, 10)
    fname = rand_ascii(r, 3, 10)
    ext = r.choice(EXTS)
    return os.path.join(base_dir, sub + "_" + fname + ext)


def rand_arch_pkgfile(r: random.Random) -> str:
    pkgver = rand_pkgver(r)
    arch = r.choice(ARCHES)
    return f"{pkgver}.{arch}.xbps"


def rand_string_for_apis(r: random.Random) -> str:
    # Mix of strings that exercise APIs: pkg names, patterns, urls, paths, random text
    choice = r.random()
    if choice < 0.15:
        return rand_pkgver(r)
    if choice < 0.30:
        return r.choice(PKG_NAMES)
    if choice < 0.45:
        return rand_pattern(r)
    if choice < 0.60:
        return rand_repo_uri(r)
    if choice < 0.75:
        return rand_arch_pkgfile(r)
    if choice < 0.90:
        # path-like
        parts = ["/", rand_ascii(r,1,6), rand_ascii(r,1,6), rand_ascii(r,1,6)]
        return "/".join([p.strip("/") for p in parts])
    # free-form small string
    return rand_ascii(r, 0, 40)


def encode_entry(kind: int, s: str) -> bytes:
    b = s.encode('utf-8', errors='ignore')
    if len(b) > 512:
        b = b[:512]
    return struct.pack('<B H', kind, len(b)) + b + b"\x00"


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    entries: List[bytes] = []

    # Ensure at least a couple of filenames and strings exist to satisfy many stubs
    num = r.randint(6, 16)

    # Pre-seed with useful canonical cases
    useful_strs = [
        "",  # empty string
        "." ,
        "..",
        "/",
        "file:///",
        "http://example.com/repo",
        "x86_64",
        "*.so",
        "libfoo>=1.2.3",
        rand_pkgver(r),
    ]
    for s in useful_strs:
        entries.append(encode_entry(0, s))

    # A few plausible filenames for FUZZ_PARAM_FILENAME consumers
    for _ in range(3):
        entries.append(encode_entry(1, rand_filename(r)))

    # Fill the rest with mixed content
    while len(entries) < num:
        if r.random() < 0.4:
            entries.append(encode_entry(1, rand_filename(r)))
        else:
            entries.append(encode_entry(0, rand_string_for_apis(r)))

    # Cap total size to 4096 bytes by truncating entries if necessary
    out = bytearray()
    out.append(min(len(entries), 255))
    total = 1
    for e in entries:
        if total + len(e) > 4096:
            break
        out.extend(e)
        total += len(e)

    return bytes(out)

import random
import string
from typing import List, Tuple

# We need to produce valid serialized proplib plist text that can be consumed by
# xbps_array_internalize() or xbps_dictionary_internalize(). The fuzzer stubs call
# these functions with FUZZ_PARAM_STR() and bail if parsing fails. So we construct
# small but varied, valid externalized plist texts for arrays or dictionaries.
#
# proplib external format is a simple textual plist-like syntax used by NetBSD proplib
# (which libxbps uses). Common constructs include:
# - arrays: ( elem, elem, ... )
# - dictionaries: { key = value; key2 = value2; }
# - strings: "text" (C-like escapes supported)
# - numbers: decimal integers
# - booleans: <true/> and <false/>
# - data (blobs): <data>hex-or-base64-like</data> (we stick to hex pairs)
# - nested arrays/dicts allowed
# - dictionary keys are identifiers or quoted strings; we will use quoted keys for safety
#
# We generate a mix of arrays and dictionaries to exercise both stubs. The buffer is a single
# NUL-terminated text string; the harness provides c_str() so just return bytes with a trailing NUL
# is not necessary, but harmless. We'll omit the explicit trailing NUL; C++ std::string c_str() adds it.

ESCAPES = ["\\\"", "\\n", "\\t", "\\r", "\\\\"]

def rnd_bool(r: random.Random) -> str:
    return "<true/>" if r.choice([True, False]) else "<false/>"

def rnd_int(r: random.Random) -> str:
    # Mix sizes, positive/negative
    choices = [0, 1, -1, 2**31-1, -2**31, 2**63-1, -2**63 + 1]
    if r.random() < 0.6:
        val = r.randint(-10**6, 10**6)
    else:
        val = r.choice(choices)
    return str(val)

def rnd_hex_data(r: random.Random, nbytes: int) -> str:
    return ''.join(r.choice('0123456789abcdef') for _ in range(nbytes*2))

def rnd_data(r: random.Random) -> str:
    # Use <data>hex</data>
    n = r.randint(0, 32)
    return f"<data>{rnd_hex_data(r, n)}</data>"

def rnd_string(r: random.Random) -> str:
    # Produce quoted string with escapes
    # Include package-like tokens and paths sometimes to trigger different code paths later
    candidates = [
        "", "a", "package", "pkg-1.0_1", "/usr/bin", "x86_64", "noarch",
        "http://example.com/repo", "foo>=1", "bar<2", "${var}", "name-version",
    ]
    if r.random() < 0.5:
        s = r.choice(candidates)
    else:
        length = r.randint(0, 32)
        alpha = string.ascii_letters + string.digits + " _-./:@"
        s = ''.join(r.choice(alpha) for _ in range(length))
        # randomly sprinkle escapes
        if s and r.random() < 0.5:
            pos = r.randrange(0, len(s))
            s = s[:pos] + r.choice(ESCAPES) + s[pos:]
    # escape quotes and backslashes
    s = s.replace('\\', r'\\').replace('"', r'\"')
    return f'"{s}"'

def rnd_value(r: random.Random, depth: int) -> str:
    # Generate a value; if depth allows, include nested arrays/dicts
    kinds = ["string", "int", "bool", "data"]
    if depth > 0:
        kinds += ["array", "dict"]
    kind = r.choice(kinds)
    if kind == "string":
        return rnd_string(r)
    if kind == "int":
        return rnd_int(r)
    if kind == "bool":
        return rnd_bool(r)
    if kind == "data":
        return rnd_data(r)
    if kind == "array":
        return gen_array(r, depth-1)
    if kind == "dict":
        return gen_dict(r, depth-1)
    return rnd_string(r)

def gen_array(r: random.Random, depth: int) -> str:
    # Format: ( v1, v2, ... )
    n = r.randint(0, 8)
    elems = [rnd_value(r, depth) for _ in range(n)]
    return "( " + ", ".join(elems) + " )"

def key_name(r: random.Random) -> str:
    # Use quoted keys to be safe
    return rnd_string(r)

def gen_dict(r: random.Random, depth: int) -> str:
    # Format: { key = value; key2 = value2; }
    n = r.randint(0, 8)
    # Always include some canonical package-like keys occasionally
    keys_base = [
        '"architecture"', '"pkgver"', '"repository"', '"provides"', '"run_depends"',
        '"conflicts"', '"alternatives"', '"scripts"', '"boolflag"', '"size"',
    ]
    entries = []
    used = set()
    for i in range(n):
        if r.random() < 0.35 and keys_base:
            k = r.choice(keys_base)
        else:
            k = key_name(r)
        # avoid duplicate textual keys for nicer dicts
        if k in used:
            k = key_name(r)
        used.add(k)
        v = rnd_value(r, depth)
        entries.append(f"{k} = {v};")
    return "{ " + " ".join(entries) + " }"

def build_root(r: random.Random) -> str:
    # Choose either an array (to exercise xbps_array_internalize) or a dict
    # (to exercise xbps_dictionary_internalize). We bias slightly towards arrays
    # since one stub requires arrays exclusively, but dictionaries also must be valid.
    if r.random() < 0.6:
        root = gen_array(r, depth=2)
        # Sometimes include heterogeneous content and nested structures already handled
    else:
        root = gen_dict(r, depth=2)
    return root

def clamp_size(s: str, maxlen: int = 4096) -> str:
    if len(s) <= maxlen:
        return s
    # Try trimming safely at a statement boundary for dict, or element boundary for array
    # Fallback to hard truncate; since we generate valid syntax, simple truncate at closing brace/paren
    cut = s.rfind(')')
    cut2 = s.rfind('}')
    cutpos = max(cut, cut2)
    if 0 < cutpos <= maxlen:
        return s[:cutpos+1]
    return s[:maxlen]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Generate multiple candidates and pick one at random to introduce variety while keeping validity
    candidates: List[str] = []
    for _ in range(5):
        txt = build_root(r)
        candidates.append(txt)
    out = r.choice(candidates)
    out = clamp_size(out, 4096)
    return out.encode('utf-8')

import os
import random
import string
from typing import List, Tuple

# Generator for serialized proplib plist content focused on arrays/dictionaries
# The fuzzers primarily read files via FUZZ_PARAM_FILENAME expecting:
#  - xbps_array_internalize_from_file: externalized array text
#  - xbps_dictionary_internalize_from_file: externalized dictionary text
#  - xbps_archive_fetch_* and *_plist: may point to archives but tolerate any file
#  - xbps_mmap_file / xbps_file_sha256*: any file
# To maximize valid parses, we emit well-formed textual proplib plist in multiple shapes
# while keeping under 4096 bytes.

# We assume NetBSD proplib externalized format used by libxbps, which accepts text forms like:
#  <array> [ elem, elem, ... ]
#  <dict> { key = value; ... }
#  Strings: "..." with C-like escapes; Booleans: <bool> true/false
#  Numbers: <integer> 123 or with size tags are often optional in xbps's proplib
#  Data blobs: <data>0xDEADBEEF</data> or <data>base64</data>; for text form, hex is commonly supported
#  Nested containers allowed.

# We will construct several templates known to parse with proplib used by xbps:
#  - Array with heterogenous elements using tagged scalar forms
#  - Dictionary with mixed scalar types
#  - Nested arrays/dicts
#  - Edge cases: empty array/dict, long strings, unicode, escape sequences
# The generator randomly chooses one and returns its bytes.

HEX_BYTES = "0123456789abcdef"


def _rand_ident(r: random.Random, minlen=3, maxlen=12) -> str:
    first = r.choice(string.ascii_letters + "_")
    rest = ''.join(r.choice(string.ascii_letters + string.digits + "_-.:") for _ in range(r.randint(minlen-1, maxlen-1)))
    return first + rest


def _rand_string(r: random.Random, minlen=0, maxlen=64) -> str:
    # Include printable, escapes, and some unicode
    length = r.randint(minlen, maxlen)
    chars = []
    for _ in range(length):
        choice = r.random()
        if choice < 0.1:
            chars.append('\n')
        elif choice < 0.2:
            chars.append('\t')
        elif choice < 0.25:
            chars.append('\r')
        elif choice < 0.35:
            chars.append('"')
        elif choice < 0.45:
            chars.append('\\')
        elif choice < 0.55:
            # some unicode BMP chars
            chars.append(chr(r.randint(0x00A0, 0x07FF)))
        else:
            chars.append(r.choice(string.printable.replace('"', '').replace('\\', '')))
    s = ''.join(chars)
    # escape per C-like within quotes
    s = s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\t', '\\t').replace('\r', '\\r')
    return f'"{s}"'


def _rand_bool(r: random.Random) -> str:
    return '<bool> true </bool>' if r.choice([True, False]) else '<bool> false </bool>'


def _rand_int(r: random.Random) -> str:
    # proplib accepts <integer> 123 </integer>
    v = r.randint(-2**63, 2**63 - 1)
    return f'<integer> {v} </integer>'


def _rand_uint(r: random.Random) -> str:
    v = r.randint(0, 2**64 - 1)
    return f'<uinteger> {v} </uinteger>'


def _rand_data_hex(r: random.Random, maxlen=64) -> str:
    nbytes = r.randint(0, maxlen)
    hexstr = ''.join(r.choice(HEX_BYTES) for _ in range(nbytes * 2))
    # proplib text accepts <data>0xHEX</data>
    return f'<data> 0x{hexstr} </data>'


def _rand_key(r: random.Random) -> str:
    # keys are quoted strings typically
    return _rand_string(r, 1, 24)


def _rand_scalar(r: random.Random) -> str:
    return r.choice([
        _rand_string(r),
        _rand_bool(r),
        _rand_int(r),
        _rand_uint(r),
        _rand_data_hex(r),
    ])


def _rand_array(r: random.Random, depth: int) -> str:
    if depth <= 0:
        count = r.randint(0, 6)
        elems = [ _rand_scalar(r) for _ in range(count) ]
    else:
        count = r.randint(0, 8)
        elems = []
        for _ in range(count):
            choice = r.random()
            if choice < 0.5:
                elems.append(_rand_scalar(r))
            elif choice < 0.75:
                elems.append(_rand_array(r, depth-1))
            else:
                elems.append(_rand_dict(r, depth-1))
    inner = ', '.join(elems)
    return f'<array> [ {inner} ] </array>'


def _rand_dict(r: random.Random, depth: int) -> str:
    if depth < 0:
        depth = 0
    count = r.randint(0, 10)
    items: List[str] = []
    for _ in range(count):
        key = _rand_key(r)
        if depth > 0 and r.random() < 0.35:
            val = _rand_array(r, depth-1)
        elif depth > 0 and r.random() < 0.5:
            val = _rand_dict(r, depth-1)
        else:
            val = _rand_scalar(r)
        items.append(f'{key} = {val};')
    inner = ' '.join(items)
    return f'<dict> {{ {inner} }} </dict>'


def _make_array_top(r: random.Random) -> str:
    # Top-level array only for xbps_array_internalize_from_file
    # Mix of scalars and nested containers
    return _rand_array(r, depth=2)


def _make_dict_top(r: random.Random) -> str:
    # Top-level dictionary for xbps_dictionary_internalize_from_file
    return _rand_dict(r, depth=2)


def _make_mixed_plist(r: random.Random) -> str:
    # Some xbps helpers accept plists inside archives; but file can be just a valid plist
    # Create a structure that looks like a package info dict often used by xbps
    name = _rand_string(r, 3, 12)
    arch = _rand_string(r, 3, 8)
    ver = _rand_string(r, 1, 10)
    provides = _rand_array(r, 1)
    rundeps = _rand_array(r, 1)
    d = [
        f'"pkgver" = {name};',
        f'"architecture" = {arch};',
        f'"version" = {ver};',
        f'"provides" = {provides};',
        f'"rundeps" = {rundeps};',
        f'"installed" = {_rand_bool(r)};',
        f'"files-hash" = {_rand_data_hex(r, 32)};',
    ]
    inner = ' '.join(d)
    return f'<dict> {{ {inner} }} </dict>'


def _ensure_max_size(s: str, limit: int = 4096) -> str:
    if len(s.encode('utf-8')) <= limit:
        return s
    # Truncate by trimming nested content conservatively: remove middle content
    # Keep outermost tags; attempt simple shrink
    while len(s.encode('utf-8')) > limit:
        # remove a chunk between separators if possible
        if ', ' in s:
            parts = s.split(', ')
            if len(parts) > 4:
                s = ', '.join(parts[:len(parts)//2])
            else:
                break
        elif ';' in s:
            parts = s.split(';')
            if len(parts) > 4:
                s = ';'.join(parts[:len(parts)//2]) + ';'
            else:
                break
        else:
            # fallback hard trim
            s = s[:limit//2]
            break
    return s


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    choice = r.random()
    if choice < 0.4:
        content = _make_array_top(r)
    elif choice < 0.8:
        content = _make_dict_top(r)
    else:
        content = _make_mixed_plist(r)
    content = _ensure_max_size(content, 4096)
    return content.encode('utf-8')

import io
import os
import random
import struct
import time
import zlib

# Generator for a compressed (zlib/deflate) buffer that contains a valid
# proplib-style plist textual representation for either an array or a dictionary.
# The target stubs call xbps_array_internalize_from_zfile() and
# xbps_dictionary_internalize_from_zfile(path). Those functions expect a path to a
# compressed file whose decompressed content is a serialized plist text. We cannot
# create files here, but the fuzz harness will place this buffer on disk and pass
# the filename. So we just need to return a compressed bytes blob that decompresses
# to a valid plist string.

# We aim to generate diverse, valid plist payloads that exercise arrays and dictionaries,
# include different scalar types, nesting, and edge cases (empty, large numbers, booleans,
# binary data, strings with escapes, unicode, and nested structures).

# Proplib textual plist format is fairly permissive and resembles Apple ASCII plist.
# Example constructs we will emit:
# - Arrays: ( a, b, c )
# - Dictionaries: { key = value; other = value; }
# - Strings: "text" or bare identifiers without spaces
# - Data: <48656c6c6f> hex
# - Booleans: <bool>yes</bool> or use 1/0 as numbers; proplib also accepts <true/>/<false/>
#   However, to stay generally compatible, we use yes/no encodings that proplib understands:
#   <true/>, <false/>
# - Numbers: decimal integers
# - Nested objects

# We also include plist headers frequently used by proplib: not strictly required for
# internalize(), but including a comment header shouldn’t hurt.

MAX_OUT = 4096

IDENT_START = "_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
IDENT_CHARS = IDENT_START + "0123456789.-_:/+@"


def _rand_ident(rng: random.Random, minlen=1, maxlen=12) -> str:
    n = rng.randint(minlen, maxlen)
    s = rng.choice(IDENT_START)
    s += "".join(rng.choice(IDENT_CHARS) for _ in range(n - 1))
    return s


def _rand_cstring(rng: random.Random, minlen=0, maxlen=32) -> str:
    # Mix ASCII, escapes, and a few unicode characters.
    length = rng.randint(minlen, maxlen)
    chars = []
    for _ in range(length):
        t = rng.random()
        if t < 0.75:
            ch = rng.randint(32, 126)
            if ch in (34, 92):  # quote or backslash -> escape
                chars.append("\\" + chr(ch))
            else:
                chars.append(chr(ch))
        elif t < 0.9:
            # common escapes
            chars.append(rng.choice(["\\n", "\\t", "\\r", "\\\"", "\\\\"]))
        else:
            # a small unicode char in BMP that’s likely to pass through
            chars.append(rng.choice(["é", "ß", "Ω", "漢", "字", "✓"]))
    return "".join(chars)


def _hex_data(rng: random.Random, minlen=0, maxlen=32) -> str:
    n = rng.randint(minlen, maxlen)
    b = rng.randbytes(n)
    return b.hex()


def _rand_int(rng: random.Random) -> int:
    # Include interesting edge values
    choices = [0, 1, -1, 2**31 - 1, -2**31, 2**63 - 1, -2**63 + 1]
    if rng.random() < 0.6:
        return rng.randint(-2**31, 2**31 - 1)
    return rng.choice(choices)


def _emit_scalar(rng: random.Random):
    kind = rng.choice(["string", "ident", "int", "bool", "data"])
    if kind == "string":
        return '"' + _rand_cstring(rng) + '"'
    if kind == "ident":
        return _rand_ident(rng)
    if kind == "int":
        return str(_rand_int(rng))
    if kind == "bool":
        return rng.choice(["<true/>", "<false/>"])
    if kind == "data":
        return "<" + _hex_data(rng) + ">"


def _emit_array(rng: random.Random, depth: int) -> str:
    n = rng.randint(0, 8 if depth < 2 else 4)
    elems = []
    for _ in range(n):
        elems.append(_emit_value(rng, depth + 1))
    return "( " + ", ".join(elems) + " )"


def _emit_dict(rng: random.Random, depth: int) -> str:
    n = rng.randint(0, 8 if depth < 2 else 4)
    items = []
    used = set()
    for _ in range(n):
        # keys as identifiers or quoted strings
        if rng.random() < 0.6:
            key = _rand_ident(rng)
        else:
            key = '"' + _rand_cstring(rng, 0, 16) + '"'
        if key in used:
            continue
        used.add(key)
        val = _emit_value(rng, depth + 1)
        items.append(f"{key} = {val};")
    return "{ " + " ".join(items) + " }"


def _emit_value(rng: random.Random, depth: int) -> str:
    if depth > 3:
        return _emit_scalar(rng)
    kind = rng.choices(["scalar", "array", "dict"], weights=[5, 3, 3], k=1)[0]
    if kind == "scalar":
        return _emit_scalar(rng)
    if kind == "array":
        return _emit_array(rng, depth)
    return _emit_dict(rng, depth)


def _emit_plist(rng: random.Random) -> str:
    # Randomly choose to emit top-level array or dictionary.
    header = "/* proplib plist */\n"
    if rng.random() < 0.5:
        body = _emit_array(rng, 0)
    else:
        body = _emit_dict(rng, 0)
    # Optionally wrap in a comment block and whitespace variations
    prefix = "" if rng.random() < 0.5 else ("\n" * rng.randint(0, 2))
    suffix = "\n" if rng.random() < 0.9 else "\n\n"
    return header + prefix + body + suffix


def _compress(data: bytes, rng: random.Random) -> bytes:
    # Use zlib with random compression level and strategy to simulate different encodings.
    level = rng.randint(0, 9)
    # zlib default wbits 15 produces zlib header; often acceptable for generic zfile
    # If the target expects gzip, this might not work, but many libxbps builds use zlib.
    # We will stick to zlib to keep things simple and valid.
    return zlib.compress(data, level)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Occasionally produce corner cases: empty array/dict or very small/large content
    choice = rng.random()
    if choice < 0.1:
        plist = "( )\n"
    elif choice < 0.2:
        plist = "{ }\n"
    else:
        plist = _emit_plist(rng)

    raw = plist.encode("utf-8")
    comp = _compress(raw, rng)

    # Ensure we do not exceed maximum output size; if we do, shrink content
    if len(comp) > MAX_OUT:
        # fallback to tiny payload
        comp = _compress(b"( 1, 2, 3 )\n", rng)

    return comp
